import {entryReady}from './entry.js?v=entry-5';
import {operations,opKeys,opLabel,opText}from './operations.js';
import {botWords}from './bot-words.js';
import {occasions,kitLines,mergeKit,recommend}from './merchandising.js';
import {salesWords}from './sales-i18n.js';
import {photoPath,artLabels,categoryArt}from './photos.js';import {ledger}from './ledger.js';
import {words,statuses} from './i18n.js';import {progressHTML,linesHTML,stageHTML,customerReviewHTML,routingHTML,historyHTML,collectionEvents,proposalHTML}from './collection.js';
import {quote as makeQuote} from './weight-policy.js';
const $=(s,r=document)=>r.querySelector(s), $$=(s,r=document)=>[...r.querySelectorAll(s)];
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const read=(k,f)=>{try{return JSON.parse(localStorage.getItem(k))??f}catch{return f}},write=(k,v)=>{try{localStorage.setItem(k,JSON.stringify(v))}catch{}};
let apiBase='',promotions=[];
const bw=k=>botWords[lang][k];
let lang=read('bazar.lang','ru');if(!words[lang])lang='ru';let city=read('bazar.city','akhalkalaki'),data,boot,user,filter='all',search='',basket=read('bazar.basket.'+city,[]),view='',tab='manageOrders',focusBefore,quoteCache,fulfillment='pickup',orders=[],staticMode=false;
const sale=k=>salesWords[lang][k]||k;
const t=k=>k==='brand'?(boot?.brand?.[lang]||words[lang].brand):(opKeys.includes(k)?opLabel(lang,k):words[lang][k]||botWords[lang][k]||k),st=k=>statuses[lang][k]||t('status'),name=o=>o?.names?.[lang]||o?.names?.ru||'',money=(v,c='GEL')=>new Intl.NumberFormat({ru:'ru-RU',hy:'hy-AM',ka:'ka-GE'}[lang],{style:'currency',currency:c,maximumFractionDigits:2}).format(v/100);
const weighted=m=>['WEIGHED','WHOLE_BY_WEIGHT','PREWEIGHED'].includes(m),unit=p=>t(p.profile.mode==='BUNCH'?'perBunch':p.profile.mode==='FIXED_PACK'?'perPack':weighted(p.profile.mode)?'perKg':'perEach');
const dayAfter=()=>new Date(Date.now()+86400000).toLocaleDateString('en-CA',{timeZone:'Asia/Tbilisi'});
const id=()=>crypto.randomUUID(),formObj=f=>Object.fromEntries(new FormData(f)),button=(a,label,extra='',cls='')=>`<button type="button" class="${cls}" data-do="${a}" ${extra}>${esc(t(label))}</button>`;
const input=(key,type='text',value='',extra='')=>`<label>${esc(t(key))}<input name="${key}" type="${type}" value="${esc(value)}" ${extra}></label>`;
const errorText=e=>t({LOGIN_TAKEN:'loginTaken',PASSWORD_TOO_SHORT:'passwordShort',INVALID_LOGIN_NAME:'loginRule',INVALID_LOGIN:'loginWrong',RATE_LIMITED:'loginWait',SELF_CHECK_FORBIDDEN:'errSelfCheck',MISSING_LINES:'errMissing',WEIGHING_REQUIRED:'errWeighing',INVALID_INVITE:'errInviteExpired',INVITE_EXPIRED:'errInviteExpired'}[e.message]||(['STALE_VERSION','QUOTE_CHANGED'].includes(e.message)?'stale':['CAPACITY_CHANGED','OUT_OF_STOCK','CONFLICT'].includes(e.message)?'stockError':['FORBIDDEN','LOGIN_REQUIRED','NOT_ASSIGNED'].includes(e.message)?'denied':e.message==='NETWORK'?'network':'error'));
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').classList.remove('show'),5000)}
async function api(path,b){let response;try{response=await fetch((apiBase||'.')+'/api/'+path,{method:b?'POST':'GET',credentials:apiBase?'omit':'same-origin',headers:b?{'Content-Type':'application/json','X-Bazar-CSRF':'1'}:{},...(b?{body:JSON.stringify(b)}:{})})}catch{throw Error('NETWORK')}let result;try{result=await response.json()}catch{throw Error('NETWORK')}if(!response.ok)throw Error(result.error||'NETWORK');return result}
function localQuote(p,selection){return makeQuote({...p.profile,id:p.id,variant_id:p.id,currency:data.city.currency,...(weighted(p.profile.mode)?{price_per_kg_minor:p.price}:{price_per_unit_minor:p.price})},selection,p.id)}
function total(){let n=0;for(const b of basket){const p=data?.products.find(p=>p.id===b.product_id);if(p)try{n+=localQuote(p,b.selection).estimate_minor}catch{}}return n}
function saveBasket(){write('bazar.basket.'+city,basket);updateBag()}
function updateBag(){$$('[data-bag]').forEach(el=>el.textContent=t('cart')+' · '+basket.length);const c=$('.sticky-cart');if(c){c.classList.toggle('hidden',!basket.length);c.innerHTML=`<span>${esc(t('cart'))} · ${basket.length}</span><span>${money(total())}</span>`}}
function productCard(p){const inCart=basket.find(b=>b.product_id===p.id);return `<article class="product"><div class="art"><img src="${esc(photoPath(p.art))}" alt="${esc(name(p))}" width="230" height="230" loading="lazy">${inCart?`<div class="quantity-picker"><button data-do="less" data-id="${esc(p.id)}" aria-label="${esc(t('remove')+' '+name(p))}">−</button><button class="qty-value" data-do="product" data-id="${esc(p.id)}">${esc(inCart.selection.grams?inCart.selection.grams+' '+t('g'):inCart.selection.count+' '+t(p.profile.mode==='BUNCH'?'bunch':p.profile.mode==='FIXED_PACK'?'pack':'each'))}</button><button data-do="more" data-id="${esc(p.id)}" aria-label="${esc(t('add')+' '+name(p))}">+</button></div>`:`<button class="add" data-do="quickadd" data-id="${esc(p.id)}" aria-label="${esc(t('add')+' '+name(p))}" ${p.available<=0?'disabled':''}>+</button>`}</div><p class="supplier">${esc(name(data.vendors.find(v=>v.id===p.vendor_id)))}</p><h3><button class="product-name" data-do="product" data-id="${esc(p.id)}">${esc(name(p))}</button></h3><div class="product-foot"><span class="price">${p.promotion_id?`<del>${money(p.regular_price)}</del> `:''}${money(p.price)}<small>${esc(unit(p))}</small></span>${inCart?`<span class="inbasket">${esc(t('cart'))}</span>`:''}</div></article>`}
function renderProducts(){const products=[...data.products].sort((a,b)=>data.categories.findIndex(c=>c.id===a.category)-data.categories.findIndex(c=>c.id===b.category)).filter(p=>(filter==='all'||p.category===filter)&&(!search||name(p).toLocaleLowerCase().includes(search.toLocaleLowerCase())));const soonCat=filter!=='all'&&!search&&!data.products.some(p=>p.category===filter)&&data.categories.find(c=>c.id===filter);$('#products').innerHTML=products.map(productCard).join('')||(soonCat?`<p class="empty">${esc(t('soonText').replace('{name}',name(soonCat)))}</p>`:`<p class="empty">${esc(t('empty'))}</p>`);$$('[data-filter]').forEach(b=>b.classList.toggle('active',b.dataset.filter===filter))}
function render(){document.documentElement.lang=lang;document.title=t('brand')+' · '+t('heroEyebrow');$('#app').innerHTML=`<div class="shell"><header><a class="brand" href="#" aria-label="${esc(t('brand'))}">${esc(t('brand'))}<small>${esc(t('tagline'))}</small></a><nav><a href="#catalog">${esc(t('catalog'))}</a><a href="#sets">${esc(t('sets'))}</a><a href="#promotions">${esc(t('promotions'))}</a><a href="#evening">${esc(t('evening'))}</a><a href="#about">${esc(t('about'))}</a></nav><div class="tools"><select id="city" aria-label="${esc(t('city'))}">${boot.cities.map(c=>`<option value="${esc(c.id)}" ${c.id===city?'selected':''}>${esc(name(c))}</option>`).join('')}</select><select id="language" aria-label="Language / Լեզու / ენა"><option value="ru" ${lang==='ru'?'selected':''}>РУС</option><option value="hy" ${lang==='hy'?'selected':''}>ՀԱՅ</option><option value="ka" ${lang==='ka'?'selected':''}>ქარ</option></select>${button('cabinet','cabinet','','staff') }<button class="bag" data-do="cart" data-bag></button></div></header><main><section class="market-hero"><div class="market-welcome"><div><p class="eyebrow">${esc(t('heroEyebrow'))}</p><h1>${esc(t('hero1'))} <em>${esc(t('hero2'))}</em></h1><p>${esc(t('heroText'))}</p></div><a class="primary market-shop" href="#catalog">${esc(t('shopNow'))}</a></div></section>${offerDoors()}${adSlot('TOP')}${promotionSections()}${salesSection()}<section id="catalog"><div class="section-head"><h2>${esc(t('season'))}</h2><label class="search"><input id="search" type="search" placeholder="${esc(t('search'))}" value="${esc(search)}" aria-label="${esc(t('search'))}"></label></div><div class="category-row">${(()=>{const has=c=>data.products.some(p=>p.category===c.id),cats=[...data.categories.filter(has),...data.categories.filter(c=>!has(c))];return ['all',...cats.map(c=>c.id)].map(c=>{const first=data.products.find(p=>p.category===c),art=first?.art||categoryArt[c];return `<button data-filter="${esc(c)}" class="${c===filter?'active':''}${c!=='all'&&!first?' soon':''}">${c!=='all'&&art?`<img src="${esc(photoPath(art))}" alt="" width="64" height="64" loading="lazy">`:''}<span>${esc(c==='all'?t('all'):name(data.categories.find(x=>x.id===c)))}${c!=='all'&&!first?`<small>${esc(t('soon'))}</small>`:''}</span></button>`}).join('')})()}</div><div class="grid" id="products"></div></section><section class="story" id="about"><div><p class="eyebrow">${esc(t('about'))}</p><h2>${esc(t('tagline'))}</h2></div><div class="steps">${[1,2,3].map(n=>`<article><b>0${n}</b><h3>${esc(t('how'+n))}</h3><p>${esc(t('how'+n+'text'))}</p></article>`).join('')}</div></section>${adSlot('FOOTER')}</main><footer><div class="brand footer-brand">${esc(t('brand'))}</div><p>${esc(t('footer'))}<br>${esc(t('photoCredit'))}${boot.contact?.address?`<br>${esc(boot.contact.address)}`:''}${boot.contact?.phone?`<br>${esc(boot.contact.phone)}`:''}</p><div>${button('orders','orders')} ${button('cabinet','cabinet')}</div></footer></div><button class="primary sticky-cart hidden" data-do="cart"></button>`;renderProducts();updateBag();entryReady()}
function open(html,kind){focusBefore=document.activeElement;$('#modal-content').innerHTML=html;view=kind;$('.modal-close').setAttribute('aria-label',t('close'));if(!$('#modal').open)$('#modal').showModal();document.body.classList.add('locked');$('#modal-content').scrollTop=0}
function close(){$('#modal').close()}
$('#modal').addEventListener('close',()=>{document.body.classList.remove('locked');view='';focusBefore?.focus?.()});$('.modal-close').onclick=close;$('#modal').addEventListener('click',e=>{if(e.target===$('#modal')){const r=$('#modal').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)close()}});
function bounds(q){return weighted(q.mode)?`${q.min_g}–${q.max_g} ${t('g')}${q.mode==='WHOLE_BY_WEIGHT'?` (${q.count} × ${q.each_min_g}–${q.each_max_g} ${t('g')})`:''}`:`${q.count} ${t(q.mode==='BUNCH'?'bunch':q.mode==='FIXED_PACK'?'pack':'each')}`}
function defaultSelection(p){return p.profile.mode==='WEIGHED'?{grams:Math.max(p.profile.minimum_g,['dried','nuts'].includes(p.category)?250:p.category==='grains'?500:1000)}:p.profile.mode==='WHOLE_BY_WEIGHT'?{count:1,range_id:p.profile.ranges[0].id}:{count:1}}
function salesSection(){return `<section class="shopping-ideas" id="sets"><div class="section-head"><div><p class="eyebrow">${esc(t('brand'))}</p><h2>${esc(sale('title'))}</h2><p class="idea-intro">${esc(sale('intro'))}</p></div></div><div class="idea-grid">${occasions.map(o=>`<button class="idea-card" data-do="idea" data-idea="${o.id}"><img src="${esc(photoPath(o.photo))}" alt="" width="320" height="220" loading="lazy"><span><strong>${esc(sale(o.id))}</strong><small>${esc(sale('browse'))}</small></span></button>`).join('')}</div></section>`}
function recommendationHTML(focus){const suggestions=recommend(data.products,city,basket,{focus,quote:localQuote});if(!suggestions.length)return '';return `<section class="recommendations"><h3>${esc(sale('pairTitle'))}</h3><p class="small">${esc(sale('pairIntro'))}</p>${suggestions.map(r=>{const p=r.product,q=localQuote(p,r.selection);return `<article class="pair-row"><img src="${esc(photoPath(p.art))}" alt="" width="72" height="72" loading="lazy"><div><button class="product-name" data-do="product" data-id="${esc(p.id)}">${esc(name(p))}</button><small>${esc(sale(r.reason))} · ${esc(bounds(q))}</small><strong>${money(q.estimate_minor)}</strong><small>${esc(t('maximum'))}: ${money(q.maximum_minor)}</small></div><button data-do="pair-add" data-id="${esc(p.id)}" data-focus="${esc(focus||'')}">${esc(sale('add'))}</button></article>`}).join('')}</section>`}
function showIdea(idea,people=4){const o=occasions.find(o=>o.id===idea);if(!o)return;const previous=view==='idea'?$$('[data-kit-key]:checked').map(x=>x.dataset.kitKey):null;const lines=kitLines(data.products,city,idea,people);open(`<img class="idea-cover" src="${esc(photoPath(o.photo))}" alt="" width="600" height="220"><h2>${esc(sale(idea))}</h2><label>${esc(sale('people'))}<select id="idea-people" data-idea="${idea}">${[2,4,6,8].map(n=>`<option value="${n}" ${n===people?'selected':''}>${n}</option>`).join('')}</select></label><p class="hint">${esc(sale('kitNote'))}</p>${lines.map(l=>{if(!l.product)return `<p class="error">${esc(sale('unavailable'))}</p>`;const p=l.product,q=localQuote(p,l.selection),available=(q.max_g??q.count)<=p.available;return `<label class="kit-row"><input type="checkbox" data-kit-key="${esc(l.key)}" ${available&&(!previous||previous.includes(l.key))?'checked':''} ${!available?'disabled':''}><img src="${esc(photoPath(p.art))}" alt="" width="64" height="64"><span><b>${esc(name(p))}</b><small>${esc(bounds(q))}${!available?' · '+esc(sale('unavailable')):''}</small></span><strong>${money(q.estimate_minor)}</strong></label>`}).join('')}<p class="small">${esc(sale('pantry'))}: ${esc(sale(idea+'Home'))}</p>${['snack','tea'].includes(idea)?`<p class="small">${esc(sale('allergy'))}</p>`:''}<div id="idea-total" data-idea="${idea}"></div><p class="small">${esc(sale('noDelivery'))}</p><button class="primary" data-do="idea-add" data-idea="${idea}">${esc(sale('kit'))}</button>`,'idea');updateIdeaTotal()}
function updateIdeaTotal(){const target=$('#idea-total');if(!target)return;const selected=new Set($$('[data-kit-key]:checked').map(x=>x.dataset.kitKey));const qs=kitLines(data.products,city,target.dataset.idea,Number($('#idea-people').value)).filter(l=>l.product&&selected.has(l.key)).map(l=>localQuote(l.product,l.selection));target.innerHTML=`<div class="totals"><div><span>${esc(sale('estimate'))}</span><strong>${money(qs.reduce((a,q)=>a+q.estimate_minor,0))}</strong></div><div><span>${esc(sale('max'))}</span><strong>${money(qs.reduce((a,q)=>a+q.maximum_minor,0))}</strong></div></div>`;$('[data-do="idea-add"]').disabled=!qs.length}
function selectProduct(pid){const p=data.products.find(p=>p.id===pid);if(!p)return;const selection=basket.find(b=>b.product_id===pid)?.selection||defaultSelection(p),m=p.profile.mode;open(`<div class="product-detail"><div class="art"><img src="${esc(photoPath(p.art))}" alt="${esc(name(p))}"></div><div><p class="supplier">${esc(name(data.vendors.find(v=>v.id===p.vendor_id)))}</p><h2>${esc(name(p))}</h2><p class="price">${money(p.price)} <small>${esc(unit(p))}</small></p><form id="product-form" data-id="${esc(pid)}">${m==='WEIGHED'?input('weight','number',selection.grams,`min="${p.profile.minimum_g}" step="${p.profile.order_step_g}" max="100000" required`):input('quantity','number',selection.count,'min="1" max="20" step="1" required')}${m==='WHOLE_BY_WEIGHT'?`<label>${esc(t('range'))}<select name="range_id">${p.profile.ranges.map(r=>`<option value="${esc(r.id)}" ${r.id===selection.range_id?'selected':''}>${r.min_g/1000}–${r.max_g/1000} ${esc(t('kg'))}</option>`).join('')}</select></label>`:''}<div id="selection-quote"></div><p class="small">${esc(t('originNote'))}</p><button class="primary" type="submit">${esc(t('add'))}</button></form></div></div>`, 'product');selectionQuote();$('#modal-content').insertAdjacentHTML('beforeend',recommendationHTML(p.id))}
function selectionFrom(f,p){const v=formObj(f);return p.profile.mode==='WEIGHED'?{grams:Number(v.weight)}:p.profile.mode==='WHOLE_BY_WEIGHT'?{count:Number(v.quantity),range_id:v.range_id}:{count:Number(v.quantity)}}
function selectionQuote(){const f=$('#product-form');if(!f)return;const p=data.products.find(p=>p.id===f.dataset.id);try{const q=localQuote(p,selectionFrom(f,p));$('#selection-quote').innerHTML=`<p class="hint">${esc(bounds(q))}<br>${esc(t(q.mode==='WEIGHED'?'weighRule':q.mode==='WHOLE_BY_WEIGHT'?'wholeRule':'fixedRule'))}</p><p>${esc(t('estimated'))}: <b>${money(q.estimate_minor)}</b><br>${esc(t('maximum'))}: <b>${money(q.maximum_minor)}</b></p>`}catch{$('#selection-quote').innerHTML=`<p class="error">${esc(t('error'))}</p>`}}
async function getQuote(){if(staticMode){const quotes=basket.map(b=>({...localQuote(data.products.find(p=>p.id===b.product_id),b.selection),names:data.products.find(p=>p.id===b.product_id).names})),fee=fulfillment==='delivery'?data.city.delivery_fee:0;return{quotes,total:quotes.reduce((s,q)=>s+q.estimate_minor,0)+fee,maximum_total:quotes.reduce((s,q)=>s+q.maximum_minor,0)+fee,delivery_fee:fee}}return api('quote',{city_id:city,items:basket,fulfillment})}
async function cart(){open(`<h2>${esc(t('cart'))}</h2><p>${esc(t('refresh'))}…</p>`,'cart');if(!basket.length){$('#modal-content').innerHTML=`<h2>${esc(t('cart'))}</h2><p class="empty">${esc(t('empty'))}</p>`;return}const q=await getQuote();quoteCache=q;if(view!=='cart')return;$('#modal-content').innerHTML=`<h2>${esc(t('cart'))}</h2>${q.quotes.map(l=>{const p=data.products.find(p=>p.id===l.product_id);return`<div class="row"><img src="${esc(photoPath(p?.art||'apple'))}" alt=""><div class="grow"><h3>${esc(name(l))}</h3><small>${esc(bounds(l))}<br>${esc(t('maximum'))} ${money(l.maximum_minor)}</small></div><strong>${money(l.estimate_minor)}</strong>${button('product','weight',`data-id="${esc(l.product_id)}"`)}${button('remove','remove',`data-id="${esc(l.product_id)}"`)}</div>`}).join('')}<p class="hint">${esc(t('weighRule'))}</p>${totals(q)}<div class="actions">${button('checkout','continue','','primary')}${button('clear','clear')}</div>${recommendationHTML()}`}
function totals(q){return `<div class="totals"><div><span>${esc(t('delivery'))}</span><span>${money(q.delivery_fee)}</span></div><div class="grand"><span>${esc(t('estimated'))}</span><strong>${money(q.total)}</strong></div><div><span>${esc(t('maximum'))}</span><b>${money(q.maximum_total)}</b></div></div>`}
async function checkout(){if(!basket.length)return cart();if(staticMode){open(`<h2>${esc(t('checkout'))}</h2><p class="hint warning">${esc(t('serverPending'))}</p>`,'pending');return}quoteCache=await getQuote();open(`<h2>${esc(t('checkout'))}</h2><form id="checkout-form"><div class="form-row">${input('name','text','','required maxlength="80" autocomplete="name"')}${input('phone','tel','','required maxlength="40" autocomplete="tel"')}</div><label>${esc(t('method'))}<select name="fulfillment"><option value="pickup" ${fulfillment==='pickup'?'selected':''}>${esc(t('pickup'))}</option><option value="delivery" ${fulfillment==='delivery'?'selected':''}>${esc(t('delivery'))}</option></select></label>${input('address','text','','maxlength="300" autocomplete="street-address"')}<div class="form-row">${input('day','date',dayAfter(),'required')}<label>${esc(t('time'))}<select name="minute" id="slot" required></select></label></div><label>${esc(t('method'))}<select name="method"><option value="cash">${esc(t('cash'))}</option><option value="transfer">${esc(t('transfer'))}</option></select></label>${input('note','text','','maxlength="400"')}<p class="hint">${esc(t('paymentNote'))}</p><div id="checkout-total">${totals(quoteCache)}</div><label class="check"><input type="checkbox" name="accepted" required><span>${esc(t('accept'))}</span></label><button type="submit" class="primary">${esc(t('submit'))}</button></form>`,'checkout');await updateSlots()}
async function updateSlots(){const f=$('#checkout-form');if(!f)return;const v=formObj(f),result=await api('slots?city='+encodeURIComponent(city)+'&day='+encodeURIComponent(v.day));if(!$('#slot'))return;$('#slot').innerHTML=result.slots.filter(s=>s.available>0).map(s=>`<option value="${s.minute}">${String(Math.floor(s.minute/60)).padStart(2,'0')}:${String(s.minute%60).padStart(2,'0')}</option>`).join('');$('#checkout-form button[type=submit]').disabled=!$('#slot').options.length}
function storedOrders(){return read('bazar.orders',[])}
async function myOrders(){const list=storedOrders();open(`<h2>${esc(t('orders'))}</h2>${list.length?list.map(o=>`<div class="row"><span>${esc(o.id)}</span>${button('track','track',`data-id="${esc(o.id)}"`)}</div>`).join(''):`<p class="empty">${esc(t('empty'))}</p>`}`,'orders')}
let tracked='';setInterval(async()=>{if(document.hidden||!$('#modal')?.open)return;const box=$('#modal-content');if(!box||box.querySelector('details[open]')||$$('input,textarea',box).some(i=>i.value!==i.defaultValue)||['INPUT','SELECT','TEXTAREA'].includes(document.activeElement?.tagName))return;try{if(view==='cabinet'&&['manageOrders','collectTab','checkTab','today','dispatch','substitutions'].includes(tab))await adminContent();else if(view==='track'&&tracked)await track(tracked)}catch{}},30000);
async function track(oid){tracked=oid;const saved=storedOrders().find(o=>o.id===oid);if(!saved)return;const o=await api('order/view',{id:oid,key:saved.key});open(orderHTML(o,true)+`<div class="actions">${boot.integrations?.telegram==='CONFIGURED'?button('bot-watch',bw('watch'),`data-id="${esc(o.id)}"`):''}${button('ref-link',opText(lang,27),`data-id="${esc(o.id)}"`)}</div><div id="customer-extra"></div>`,'track')}
const eventLabels={...collectionEvents,CREATED:'placed',CLAIM:'claim',CONFIRM:'confirm',AVAILABLE:'available',MISSING:'missing',PREPARE:'prepare',READY:'ready',WEIGH:'weigh',REPLACE:'replace',CHANGE_APPROVED:'approve',CHANGE_REJECTED:'reject',PICKUP:'pick',DEPART:'depart',DELIVER:'deliver',HANDOVER:'handover',PAYMENT:'payment',CANCEL:'cancel',SETTLEMENT:'settle',PAYMENT_REPORTED:'paymentReview',PAYMENT_REVIEWED:'payment'};
function orderHTML(o,customer=false){const owner=o.role==='OWNER',driver=o.role==='DRIVER'||owner&&o.driver_id===user.id,collector=o.role==='COLLECTOR',terminal=['COMPLETED','CANCELLED'].includes(o.status),work=o.confirmed&&['WEIGHING','ASSEMBLING'].includes(o.status),canWeigh=!customer&&(owner||collector||o.role==='SUPPLIER')&&work,cc={t,esc,name,money,bounds,button,lang,eventName:k=>t(eventLabels[k]||'status')};return `<article class="panel" data-order="${esc(o.id)}"><div style="display:flex;justify-content:space-between;gap:12px"><h3>${esc(o.id)}</h3><span>${esc(o.day)} · ${String(Math.floor(o.minute/60)).padStart(2,'0')}:${String(o.minute%60).padStart(2,'0')}</span></div><span class="badge">${esc(st(o.status))}</span>${o.payment?`<span class="badge warm">${esc(st(o.payment))}</span>`:''}${o.role&&o.role!=='OWNER'&&!customer?`<span class="badge muted">${esc(st(o.role))}</span>`:''}${progressHTML(o,cc)}${o.customer?`<p>${o.customer.name?esc(o.customer.name)+' · '+esc(o.customer.phone)+'<br>'+esc(o.customer.address)+' ':''}${esc(o.customer.note)}</p>`:''}${o.total!==null&&o.total!==undefined?`<p>${esc(t(o.proposal?'proposalWas':o.actuals?'finalTotal':'total'))}: <b>${money(o.total,o.currency)}</b>${o.paid!==null&&o.paid!==undefined&&(!customer||o.paid>0)?` · ${esc(t('paid'))}: ${money(o.paid,o.currency)}`:''}</p>`:''}${linesHTML(o,cc,canWeigh)}${proposalHTML(o,cc,customer)}${customer?customerReviewHTML(o,cc):''}${o.groups?.map(g=>`<div class="row"><div class="grow"><small>${esc(name(data.vendors.find(v=>v.id===g.vendor_id)))}</small>${['OWNER','DRIVER'].includes(o.role)?`<small>${esc(data.vendors.find(v=>v.id===g.vendor_id)?.address||'')} ${esc(data.vendors.find(v=>v.id===g.vendor_id)?.phone||'')}</small>`:''}<span class="badge">${esc(st(g.status))}</span></div>${!customer&&(owner||collector||o.role==='SUPPLIER'&&user.memberships.some(m=>m.vendor_id===g.vendor_id))&&work?`<div class="actions">${(g.status==='WAITING'||g.status==='MISSING'?[['available','available']]:[]).concat(['WAITING','AVAILABLE','PREPARING'].includes(g.status)?[['missing','missing']]:[],g.status==='AVAILABLE'?[['prepare','prepare']]:[],g.status==='PREPARING'&&o.actuals?[['ready','ready']]:[]).map(([a,l])=>button('act',l,`data-action="${a}" data-id="${esc(o.id)}" data-version="${o.version}" data-vendor="${esc(g.vendor_id)}"`)).join('')}</div>`:''}</div>`).join('')||''}${!customer&&!terminal?stageHTML(o,cc)+`<div class="actions">${o.fulfillment==='delivery'&&!o.driver_id&&(owner||o.role==='UNASSIGNED_DRIVER')?actButton(o,'claim','claim'):''}${!o.confirmed&&(owner||driver)?actButton(o,'confirm','confirm'):''}${driver&&o.status==='READY'?actButton(o,'pickup','pick'):''}${driver&&o.status==='PICKED_UP'?actButton(o,'depart','depart'):''}${driver&&o.status==='OUT_FOR_DELIVERY'?actButton(o,'deliver','deliver'):''}${owner&&o.fulfillment==='pickup'&&o.status==='READY'?actButton(o,'handover','handover'):''}${owner?actButton(o,'cancel','cancel'):''}</div>`:''}${!customer&&(owner||driver||collector||o.role==='SUPPLIER')&&!terminal&&['WEIGHING','ASSEMBLING','AWAITING_APPROVAL'].includes(o.status)?replacementForm(o):''}${owner&&o.actuals&&o.payment!=='PAID'&&!['CANCELLED','AWAITING_APPROVAL'].includes(o.status)?`<details><summary>${esc(t('payment'))}</summary><form class="payment-form" data-id="${esc(o.id)}" data-version="${o.version}"><div class="form-row">${input('amount','number',((o.total-o.paid)/100).toFixed(2),'min="0.01" step="0.01" required')}${input('reason','text','','required maxlength="300"')}</div><button type="submit">${esc(t('payment'))}</button></form></details>`:''}${owner&&o.status==='COMPLETED'&&o.payment==='PAID'?settlementForm(o):''}${o.original_quotes?`<details><summary>${esc(t('original'))}</summary>${o.original_quotes.map(l=>`<p>${esc(name(l))} · ${esc(bounds(l))}${o.total===null?'':' · '+money(l.estimate_minor,o.currency)}</p>`).join('')}</details>`:''}${owner?routingHTML(o,cc):''}${historyHTML(o,cc)}</article>`}
function shareHTML(url,hint){return `<p class="hint">${esc(hint)}</p><input readonly value="${esc(url)}" aria-label="${esc(t('invite'))}"><div class="actions">${button('copy','copy',`data-value="${esc(url)}"`,'primary')}${navigator.share?button('share','invite',`data-value="${esc(url)}"`):''}</div>`}
