function replacementForm(o){return `<details><summary>${esc(t('replace'))}</summary><p class="hint">${esc(t('replacementHint'))}</p><form class="replace-form" data-id="${esc(o.id)}" data-version="${o.version}"><label>${esc(t('original'))}<select name="old">${o.quotes.map(l=>`<option value="${esc(l.product_id)}">${esc(name(l))}</option>`).join('')}</select></label><label>${esc(t('newProduct'))}<select name="new"><option value="">${esc(t('removeLine'))}</option>${data.products.filter(p=>p.available>0&&(o.role!=='SUPPLIER'||user.memberships.some(m=>m.vendor_id===p.vendor_id&&m.role!=='DRIVER'))).map(p=>`<option value="${esc(p.id)}">${esc(name(p))}</option>`).join('')}</select></label><button type="submit">${esc(t('replace'))}</button></form></details>`}
