function settlementForm(o){return `<details><summary>${esc(t('settle'))}</summary><p class="hint">${esc(t('netHint'))}</p><form class="settle-form" data-id="${esc(o.id)}"><div class="form-row">${costKeys.map(k=>`<label>${esc(t(k==='payment'?'paymentFee':k))}<input name="${k}" type="number" min="0" step="0.01" required></label>`).join('')}</div>${input('evidence','text','','required maxlength="1000"')}<label class="check"><input name="confirmed" type="checkbox" required>${esc(t('costsConfirmed'))}</label><button type="submit">${esc(t('save'))}</button></form></details>`}
async function cabinet(){if(apiBase){location.assign(apiBase+'/#cabinet');return}if(!user){open(`<h2>${esc(t('login'))}</h2><p>${esc(t('loginHint'))}</p>${staticMode?`<p class="hint warning">${esc(t('serverPending'))}</p>`:`<form id="login-form"><label>${esc(t('loginOrEmail'))}<input name="email" type="text" required autocomplete="username" autocapitalize="none" spellcheck="false"></label>${input('password','password','','required autocomplete="current-password"')}<button class="primary" type="submit">${esc(t('signin'))}</button></form>`}`,'login');return}const role=user.owner?'OWNER':user.team?.[0]?.role||user.memberships?.[0]?.role||'STAFF',tabs=user.owner?['today','manageOrders','collectTab','checkTab','dispatch','substitutions','suppliers','ledger','couriers','cashDesk','telegram','inventory','promotions','evening','referrals','customers','payments','finance','advertising','team','audit','integrations']:role==='COLLECTOR'?['collectTab','manageOrders','telegram']:role==='CONTROLLER'?['checkTab','collectTab','manageOrders','telegram']:['manageOrders',...(user.memberships.some(m=>m.role==='DRIVER')?['couriers']:['inventory','ledger']),'telegram'];if(!tabs.includes(tab))tab=tabs[0];open(`<h2>${esc(t('cabinet'))}</h2><p>${esc(user.name)} · ${esc(st(role))}</p><div class="tabs operations-tabs">${tabs.map(s=>button('tab',s,`data-tab="${s}"`,tab===s?'active':'')).join('')}</div><div id="admin-content"><p>${esc(t('refresh'))}…</p></div><div class="actions">${button('admin-refresh','refresh')}${user.auth_mode==='sites'?'':button('logout','logout')}</div>`,'cabinet');await adminContent()}
async function adminContent(){if(view!=='cabinet')return;const ctx={api,city,data,user,lang,esc,name,money,st,orderHTML,setOrders:list=>{orders=list},eventName:k=>t(eventLabels[k]||'status'),refresh:async()=>{boot=await api('bootstrap');data=await api('catalog?city='+city);promotions=(await api('promotions?city='+city)).promotions;render();await adminContent()},toast,errorText};if(await ledger(tab,ctx)||await operations(tab,ctx))return;let html='';if(['manageOrders','collectTab','checkTab'].includes(tab)){orders=(await api('manage/orders?city='+city)).orders;const queue={collectTab:['NEW','WEIGHING','ASSEMBLING','AWAITING_APPROVAL'],checkTab:['CHECKING','CUSTOMER_REVIEW']}[tab];html=orders.filter(o=>!queue||queue.includes(o.status)).map(o=>orderHTML(o)).join('')||`<p class="empty">${esc(t('empty'))}</p>`}
if(tab==='inventory'){const result=await api('manage/catalog?city='+city);html=catalogForms()+result.products.map(p=>`<details class="panel"><summary>${esc(name(p))} · ${money(p.price)} · ${esc(t('stock'))}: ${p.stock} ${esc(t(weighted(p.profile.mode)?'g':'each'))}</summary><p>${esc(t('reserved'))}: ${p.reserved}</p><form class="inventory-form" data-id="${esc(p.id)}" data-version="${p.version}"><div class="form-row"><label>${esc(t('inventory'))}<select name="action"><option value="receipt">${esc(t('receipt'))}</option><option value="loss">${esc(t('loss'))}</option></select></label>${input('quantity','number','','min="1" step="1" required')}</div>${input('reason','text','','required maxlength="300"')}<button type="submit">${esc(t('save'))}</button></form>${user.owner||user.memberships.some(m=>m.vendor_id===p.vendor_id&&m.role==='ADMIN')?`<form class="product-edit" data-id="${esc(p.id)}" data-version="${p.version}">${['ru','hy','ka'].map(l=>`<label>${{ru:'Русский',hy:'Հայերեն',ka:'ქართული'}[l]}<input name="${l}" value="${esc(p.names[l])}" required maxlength="120"></label>`).join('')}<div class="form-row">${input('price','number',(p.price/100).toFixed(2),'min="0" step="0.01" required')}${input('cost','number',p.cost===null?'':(p.cost/100).toFixed(2),'min="0" step="0.01"')}</div>${input('reason','text','','required')}<label class="check"><input type="checkbox" name="active" ${p.active?'checked':''}>${esc(t('available'))}</label><button type="submit">${esc(t('save'))}</button></form>`:''}</details>`).join('')||`<p>${esc(t('empty'))}</p>`}
if(tab==='suppliers'){const labels=['ru','hy','ka'].map(l=>`<label>${{ru:'Русский',hy:'Հայերեն',ka:'ქართული'}[l]}<input name="${l}" required maxlength="120"></label>`).join('');html=`${data.vendors.map(v=>`<article class="panel"><h3>${esc(name(v))}</h3><p>${esc(v.address)}<br>${esc(v.phone)}</p></article>`).join('')}<details class="panel"><summary>${esc(t('newSupplier'))}</summary><form id="vendor-create">${input('code','text','','required pattern="[a-z][a-z0-9-]{1,59}"')}${labels}${input('address','text','','maxlength="300"')}${input('phone','tel','','maxlength="40"')}<button type="submit">${esc(t('save'))}</button></form></details><details class="panel"><summary>${esc(t('newCity'))}</summary><form id="city-create">${input('code','text','','required pattern="[a-z][a-z0-9-]{1,59}"')}${labels}${input('delivery','number',0,'min="0" step="0.01" required')}<button type="submit">${esc(t('save'))}</button></form></details>`}
if(tab==='team'){const r=await api('manage/team'),staff=new Set(r.team.map(m=>m.user_id));html=`<section class="panel"><h3>${esc(t('teamTitle'))}</h3><p class="hint">${esc(t('staffHint'))}</p><form id="team-create-form"><div class="form-row"><label>${esc(t('role'))}<select name="role">${['COLLECTOR','CONTROLLER'].map(r=>`<option value="${r}">${esc(st(r))}</option>`).join('')}</select></label><label>${esc(t('city'))}<select name="city_id">${boot.cities.map(c=>`<option value="${esc(c.id)}" ${c.id===city?'selected':''}>${esc(name(c))}</option>`).join('')}</select></label></div><label>${esc(t('staffName'))}<input name="name" required maxlength="100"></label><div class="form-row"><label>${esc(t('loginField'))}<input name="login" required pattern="[a-zA-Z0-9._-]{2,40}" autocapitalize="none" spellcheck="false" autocomplete="off"></label><label>${esc(t('passwordField'))}<input name="password" type="text" required minlength="6" autocomplete="off"></label></div><button type="submit" class="primary">${esc(t('createStaff'))}</button></form>${r.team.map(m=>`<div class="row"><div class="grow"><h3>${esc(m.name)}</h3><small>${esc(t('loginField'))}: <b>${esc(m.login)}</b> · ${esc(st(m.role))} · ${esc(name(boot.cities.find(c=>c.id===m.city_id)))} · ${esc(bw(m.linked?'linkedYes':'linkedNo'))}</small><form class="staff-password-form form-row" data-user="${esc(m.user_id)}"><label>${esc(t('newPassword'))}<input name="password" type="text" required minlength="6" autocomplete="off"></label><button type="submit">${esc(t('setPassword'))}</button></form></div>${button('revoke-team','revoke',`data-user="${esc(m.user_id)}" data-city="${esc(m.city_id)}"`)}</div>`).join('')}<p class="hint">${esc(bw('teamLink'))}</p></section><p class="hint">${esc(t('inviteHint'))}</p><form id="invite-form"><label>${esc(t('supplier'))}<select name="vendor_id">${data.vendors.map(v=>`<option value="${esc(v.id)}">${esc(name(v))}</option>`).join('')}</select></label><label>${esc(t('role'))}<select name="role">${['ADMIN','STAFF','SUPPLIER','DRIVER'].map(r=>`<option value="${r}">${esc(st(r))}</option>`).join('')}</select></label><button type="submit">${esc(t('invite'))}</button></form><div id="invite-result"></div>${r.members.filter(m=>m.vendor_id||!staff.has(m.id)).map(m=>`<div class="row"><div class="grow"><h3>${esc(m.name)}</h3><small>${esc(m.email)} · ${esc(st(m.role||'OWNER'))} · ${esc(name(data.vendors.find(v=>v.id===m.vendor_id)))}</small></div>${m.vendor_id?button('revoke','revoke',`data-user="${esc(m.id)}" data-vendor="${esc(m.vendor_id)}"`):''}</div>`).join('')}`}
if(tab==='finance'){const r=await api('manage/summary?city='+city);html=`<div class="numbers">${[['revenue',r.revenue],['received',r.received],['debt',r.debt],['gross',r.gross_profit],['expenses',r.expenses]].map(([k,v])=>`<div class="number"><small>${esc(t(k))}</small><strong>${v===null?esc(t('unknown')):money(v)}</strong></div>`).join('')}</div><p class="hint">${esc(t('netHint'))}</p>${r.settlements.map(s=>`<div class="row"><span>${esc(s.order_id)} · ${esc(t(s.state==='CLOSED'?'closed':'shortfall'))}</span><strong>${money(s.net)}</strong></div>`).join('')}<details><summary>${esc(t('expenseNew'))}</summary><form id="expense-form"><div class="form-row">${input('amount','number','','min="0.01" step="0.01" required')}<label>${esc(t('expenses'))}<select name="category">${costKeys.map(k=>`<option value="${k}">${esc(t(k==='payment'?'paymentFee':k))}</option>`).join('')}</select></label></div>${input('reason','text','','required')}<button type="submit">${esc(t('save'))}</button></form></details><table><thead><tr><th>${esc(t('day'))}</th><th>${esc(t('orders'))}</th><th>${esc(t('revenue'))}</th></tr></thead><tbody>${r.history.map(d=>`<tr><td>${esc(d.day)}</td><td>${d.orders}</td><td>${money(d.revenue)}</td></tr>`).join('')}</tbody></table>`}
if(tab==='integrations'){const r=user.owner?await api('manage/summary?city='+city):{},tg=boot.integrations?.telegram==='CONFIGURED'?await api('manage/telegram/status'):null,chats=tg?tg.links.filter(l=>l.active).length:0;html=`<div class="row"><h3>${esc(t('telegram'))}</h3><span class="badge ${chats?'':'warm'}">${esc(tg?bw('connected')+': '+chats:bw('setup'))}</span>${button('tab','telegram','data-tab="telegram"')}</div>${tg&&!chats?`<p class="hint warning">${esc(bw('noRoutes'))}</p>`:''}<div class="row"><h3>${esc(t('sheets'))}</h3><span class="badge warm">${esc(t('disabled'))}</span></div><p>${esc(t('queue'))}: ${r.queued||0}</p>`}if(view==='cabinet'&&$('#admin-content'))$('#admin-content').innerHTML=html}
function catalogForms(){if(!user.owner&&!user.memberships.some(m=>m.role==='ADMIN'))return '';const nfields=['ru','hy','ka'].map(l=>`<label>${{ru:'Русский',hy:'Հայերեն',ka:'ქართული'}[l]}<input name="${l}" required maxlength="120"></label>`).join('');return `<details class="panel"><summary>${esc(t('newProductTitle'))}</summary><p class="hint">${esc(t('catalogAddHint'))}</p><form id="product-create">${input('code','text','','required pattern="[a-z][a-z0-9-]{1,59}"')}${nfields}<div class="form-row"><label>${esc(t('supplier'))}<select name="vendor_id">${data.vendors.filter(v=>user.owner||user.memberships.some(m=>m.vendor_id===v.id&&m.role==='ADMIN')).map(v=>`<option value="${esc(v.id)}">${esc(name(v))}</option>`).join('')}</select></label><label>${esc(t('category'))}<select name="category">${data.categories.map(c=>`<option value="${esc(c.id)}">${esc(name(c))}</option>`).join('')}</select></label></div><label>${esc(t('art'))}<select name="art">${[...new Map(data.products.map(p=>[p.art,p])).values()].map(p=>`<option value="${esc(p.art)}">${esc(name(p))}</option>`).join('')}${Object.entries(artLabels).filter(([k])=>!data.products.some(p=>p.art===k)).map(([k,n])=>`<option value="${esc(k)}">${esc(n[lang]||n.ru)}</option>`).join('')}</select></label><label>${esc(t('saleMode'))}<select name="mode"><option value="WEIGHED">${esc(t('weighedMode'))}</option><option value="EACH">${esc(t('eachMode'))}</option><option value="BUNCH">${esc(t('bunchMode'))}</option><option value="FIXED_PACK">${esc(t('packMode'))}</option></select></label><div class="form-row">${input('price','number','','min="0" step="0.01" required')}${input('cost','number','','min="0" step="0.01"')}${input('stock','number',0,'min="0" step="1" required')}</div><div class="form-row">${input('minimum','number',100,'min="1" step="1"')}${input('step','number',50,'min="1" step="1"')}${input('cap','number',20,'min="0" max="200" step="1"')}${input('declared','number',250,'min="1" step="1"')}</div>${input('reason','text','','required')}<button type="submit">${esc(t('save'))}</button></form></details>${user.owner?`<details class="panel"><summary>${esc(t('newCategory'))}</summary><form id="category-create">${input('code','text','','required pattern="[a-z][a-z0-9-]{1,59}"')}${nfields}<button type="submit">${esc(t('save'))}</button></form></details>`:''}`}
async function doAction(el){const a=el.dataset.do,pid=el.dataset.id;if(['quickadd','more','less'].includes(a)){const p=data.products.find(p=>p.id===pid),current=basket.find(b=>b.product_id===pid);if(p.profile.mode==='WHOLE_BY_WEIGHT'){selectProduct(pid);return}let selection=structuredClone(current?.selection||defaultSelection(p));if(current){if(selection.grams){selection.grams+=(a==='less'?-1:1)*p.profile.order_step_g;if(selection.grams<p.profile.minimum_g)selection=null}else{selection.count+=a==='less'?-1:1;if(selection.count<1)selection=null}}if(selection){const q=localQuote(p,selection);if((weighted(q.mode)?q.max_g:q.count)>p.available)throw Error('OUT_OF_STOCK')}basket=basket.filter(b=>b.product_id!==pid);if(selection)basket.push({product_id:pid,selection});saveBasket();renderProducts()}else if(a==='product')selectProduct(pid);else if(a==='cart')await cart();else if(a==='remove'){basket=basket.filter(b=>b.product_id!==pid);saveBasket();renderProducts();await cart()}else if(a==='clear'){const previous=basket; basket=[];saveBasket();renderProducts();await cart();toast(t('saved'));window.bazarUndo=()=>{basket=previous;saveBasket();renderProducts();cart()};$('#modal-content').innerHTML+=button('undo','undo')}else if(a==='undo')window.bazarUndo?.();else if(a==='checkout')await checkout();else if(a==='orders')await myOrders();else if(a==='track')await track(pid);else if(a==='cabinet')await cabinet();else if(a==='tab'){tab=el.dataset.tab;await cabinet()}else if(a==='admin-refresh')await adminContent();else if(a==='logout'){await api('logout',{});user=null;await cabinet()}else if(a==='idea'){showIdea(el.dataset.idea)}else if(a==='pair-add'){const p=data.products.find(p=>p.id===pid);const suggestion=recommend(data.products,city,basket,{focus:el.dataset.focus||undefined,limit:100,quote:localQuote}).find(x=>x.product.id===pid);if(!suggestion)throw Error('OUT_OF_STOCK');basket=mergeKit(basket,[suggestion],localQuote);saveBasket();renderProducts();if(view==='cart')await cart();else if(view==='product')selectProduct(el.dataset.focus);toast(t('saved'))}else if(a==='idea-add'){const selected=$$('[data-kit-key]:checked').map(x=>x.dataset.kitKey),lines=kitLines(data.products,city,el.dataset.idea,Number($('#idea-people').value)).filter(l=>selected.includes(l.key));if(!lines.length){toast(sale('none'));return}basket=mergeKit(basket,lines,localQuote);saveBasket();renderProducts();await cart()}else if(['approve','reject'].includes(a)){const saved=storedOrders().find(o=>o.id===pid);await api('order/approve',{id:pid,key:saved.key,version:Number(el.dataset.version),proposal_id:el.dataset.proposal,approved:a==='approve'});await track(pid)}else if(a==='bot-watch'){const o=storedOrders().find(o=>o.id===pid),r=await api('order/telegram',{...o,lang});$('#customer-extra').innerHTML=`<p class="hint">${esc(bw('privateHint'))}</p><div class="actions"><a class="button primary" href="${esc(r.url)}" target="_blank" rel="noopener">${esc(bw('openTelegram'))}</a></div><p class="hint">${esc(bw('validUntil'))} ${esc(new Date(r.expires_at||Date.now()+r.expires_in*1000).toLocaleTimeString(lang,{hour:'2-digit',minute:'2-digit'}))}</p>`}else if(a==='ref-link'){const o=storedOrders().find(o=>o.id===pid),r=await api('order/referral',o);$('#customer-extra').innerHTML=r?`<p>${esc(opText(lang,29))}: ${money(r.balance)} · ${esc(opText(lang,30))}: ${r.friends}</p>${r.active?`<input readonly value="https://xugushik-source.github.io/Bazar/?ref=${esc(r.code)}"><p>${r.reward_percent}% · ${esc(r.until_at)} · ${r.points_days} ${esc(t('day'))}</p>`:`<p>${esc(opText(lang,36))}</p>`}`:''}else if(a==='phone-answer'){const reason=prompt(t('phoneNoteAsk'));if(!reason?.trim())return;await api('manage/approve-phone',{id:pid,version:Number(el.dataset.version),proposal_id:el.dataset.proposal,approved:el.dataset.approved==='1',reason:reason.trim()});await adminContent()}else if(a==='confirm-collection'||a==='dispute-collection'){const saved=storedOrders().find(o=>o.id===pid),b={id:pid,key:saved.key,version:Number(el.dataset.version),accepted:a==='confirm-collection'};if(!b.accepted){const reason=prompt(t('disputeAsk'));if(!reason?.trim())return;b.reason=reason.trim()}await api('order/confirm',b);await track(pid)}else if(a==='act'){const b={id:pid,version:Number(el.dataset.version),command:id(),action:el.dataset.action,...(el.dataset.vendor?{vendor_id:el.dataset.vendor}:{}),...(el.dataset.line?{line_id:el.dataset.line}:{})};const ask={cancel:'reason',return_collection:'returnReasonAsk',confirm_phone:'phoneNoteAsk'}[b.action];if(ask){const reason=prompt(t(ask));if(!reason?.trim())return;b.reason=reason.trim()}await api('manage/action',b);await adminContent()}else if(a==='copy'){try{await navigator.clipboard.writeText(el.dataset.value);toast(bw('copied'))}catch{const i=el.parentElement.parentElement.querySelector('input[readonly]');i?.select();toast(bw('copy'))}}else if(a==='share'){try{await navigator.share({url:el.dataset.value})}catch{}}else if(a==='revoke-team'){await api('manage/team/revoke',{user_id:el.dataset.user,city_id:el.dataset.city});await adminContent()}else if(a==='revoke'){await api('manage/revoke',{user_id:el.dataset.user,vendor_id:el.dataset.vendor});await adminContent()}}
document.addEventListener('click',async e=>{const filterEl=e.target.closest('[data-filter]');if(filterEl){filter=filterEl.dataset.filter;renderProducts();return}const el=e.target.closest('[data-do]');if(!el)return;el.disabled=true;try{await doAction(el)}catch(err){toast(errorText(err))}finally{el.disabled=false}});
document.addEventListener('input',e=>{if(e.target.id==='search'){search=e.target.value;renderProducts()}if(e.target.closest('#product-form'))selectionQuote()});
document.addEventListener('change',async e=>{try{if(e.target.id==='idea-people'){showIdea(e.target.dataset.idea,Number(e.target.value));return}if(e.target.matches('[data-kit-key]')){updateIdeaTotal();return}if(e.target.id==='language'){lang=e.target.value;write('bazar.lang',lang);render();if($('#modal').open)close()}if(e.target.id==='city'){city=e.target.value;write('bazar.city',city);basket=read('bazar.basket.'+city,[]);data=staticMode?(await fetch('./catalogue.json').then(r=>r.json())).catalogues[city]:await api('catalog?city='+city);promotions=staticMode?[]:(await api('promotions?city='+city)).promotions;render()}if(e.target.closest('#checkout-form')){if(e.target.name==='day')await updateSlots();if(e.target.name==='fulfillment'){fulfillment=e.target.value;quoteCache=await getQuote();$('#checkout-total').innerHTML=totals(quoteCache);$('[name=accepted]').checked=false}}}catch(err){toast(errorText(err))}});
document.addEventListener('submit',async e=>{if(e.target.matches('[data-ops-form]'))return;e.preventDefault();const f=e.target,v=formObj(f),submit=$('button[type=submit]',f);if(submit)submit.disabled=true;try{
if(f.id==='product-form'){const p=data.products.find(p=>p.id===f.dataset.id),selection=selectionFrom(f,p);localQuote(p,selection);basket=basket.filter(b=>b.product_id!==p.id).concat({product_id:p.id,selection});saveBasket();renderProducts();toast(t('saved'));close()}
else if(f.id==='checkout-form'){const base={city_id:city,items:basket,ref:read('bazar.ref',''),fulfillment,day:v.day,minute:Number(v.minute),method:v.method,customer:{name:v.name,phone:v.phone,address:v.address,note:v.note},expected_total:quoteCache.total,maximum_total:quoteCache.maximum_total,accepted_weight_rules:v.accepted==='on'},fingerprint=JSON.stringify(base),pending=read('bazar.pending',null),b={...base,idem:pending?.fingerprint===fingerprint?pending.idem:id()};write('bazar.pending',{fingerprint,idem:b.idem});const result=await api('orders',b);write('bazar.orders',storedOrders().filter(o=>o.id!==result.id).concat({id:result.id,key:result.key}));write('bazar.pending',null);basket=[];saveBasket();renderProducts();toast(t('placed'));await track(result.id)}
else if(f.id==='login-form'){await api('login',v);user=(await api('bootstrap')).user;await cabinet()}
else if(f.classList.contains('weigh-form')){const list=s=>s.split(',').map(v=>v.trim()).filter(Boolean).map(Number),actuals=$$('[data-line]',f).filter(x=>x.value.trim()).map(x=>{const pack=x.dataset.mode==='FIXED_PACK'?list($(`[data-pack="${CSS.escape(x.dataset.line)}"]`,f)?.value||''):[];return {line_id:x.dataset.line,...(pack.length?{each_net_g:pack}:{}),...(x.dataset.mode==='WHOLE_BY_WEIGHT'?{each_net_g:list(x.value)}:weighted(x.dataset.mode)?{net_g:Number(x.value)}:{count:Number(x.value)})}});if(!actuals.length){toast(t('weighHelp'));return}await api('manage/action',{id:f.dataset.id,version:Number(f.dataset.version),command:id(),action:'weigh',actuals});await adminContent()}
else if(f.classList.contains('replace-form')){const o=orders.find(o=>o.id===f.dataset.id),p=v.new?data.products.find(p=>p.id===v.new):null,items=o.quotes.filter(l=>l.product_id!==v.old).map(l=>({product_id:l.product_id,selection:l.selection}));if(p&&items.some(i=>i.product_id===p.id))throw Error('INVALID_INPUT');if(p)items.push({product_id:p.id,selection:defaultSelection(p)});await api('manage/action',{id:o.id,version:o.version,command:id(),action:'replace',items});await adminContent()}
else if(f.classList.contains('payment-form')){await api('manage/action',{id:f.dataset.id,version:Number(f.dataset.version),command:id(),action:'payment',amount:Math.round(Number(v.amount)*100),reason:v.reason});await adminContent()}
else if(f.classList.contains('inventory-form')){await api('manage/inventory',{product_id:f.dataset.id,version:Number(f.dataset.version),command:id(),action:v.action,quantity:Number(v.quantity),reason:v.reason});await adminContent()}
else if(f.classList.contains('product-edit')){await api('manage/product',{id:f.dataset.id,version:Number(f.dataset.version),names:{ru:v.ru,hy:v.hy,ka:v.ka},price:Math.round(Number(v.price)*100),cost:v.cost===''?null:Math.round(Number(v.cost)*100),active:v.active==='on',reason:v.reason});data=await api('catalog?city='+city);renderProducts();await adminContent()}
else if(f.id==='invite-form'){const r=await api('manage/invite',v),url=new URL(location.href);url.hash='join='+r.invite;$('#invite-result').innerHTML=shareHTML(url.href,t('inviteHint'))}else if(f.id==='team-create-form'){await api('manage/team/create',v);toast(t('staffCreated'));await adminContent()}else if(f.classList.contains('staff-password-form')){await api('manage/team/password',{user_id:f.dataset.user,password:v.password});f.reset();toast(t('passwordSaved'))}
else if(f.id==='join-form'){await api('join',{...v,invite:new URLSearchParams(location.hash.slice(1)).get('join')});history.replaceState(null,'',location.pathname);toast(t('saved'));await cabinet()}
else if(f.classList.contains('settle-form')){const r=await api('manage/summary?city='+city),old=r.settlements.find(s=>s.order_id===f.dataset.id),expenses=Object.fromEntries(costKeys.map(k=>[k,Math.round(Number(v[k])*100)])),result=await api('manage/settle',{id:f.dataset.id,command:id(),version:old?.version||0,expenses,costs_confirmed:v.confirmed==='on',evidence:v.evidence});toast(t(result.state==='CLOSED'?'closed':'shortfall'));await adminContent()}
else if(['vendor-create','city-create'].includes(f.id)){await api('manage/'+(f.id==='vendor-create'?'vendor':'city')+'/create',{code:v.code,names:{ru:v.ru,hy:v.hy,ka:v.ka},city_id:city,address:v.address||'',phone:v.phone||'',delivery_fee:Math.round(Number(v.delivery||0)*100),command:id()});boot=await api('bootstrap');data=await api('catalog?city='+city);render();await cabinet()}
else if(f.id==='category-create'){await api('manage/category/create',{id:v.code,names:{ru:v.ru,hy:v.hy,ka:v.ka},sort:50,command:id()});data=await api('catalog?city='+city);render();await cabinet()}
else if(f.id==='product-create'){await api('manage/product/create',{code:v.code,names:{ru:v.ru,hy:v.hy,ka:v.ka},vendor_id:v.vendor_id,category:v.category,art:v.art,mode:v.mode,price:Math.round(Number(v.price)*100),cost:v.cost===''?null:Math.round(Number(v.cost)*100),stock:Number(v.stock),minimum_g:Number(v.minimum),order_step_g:Number(v.step),tolerance_cap_g:Number(v.cap),declared_net_g:Number(v.declared),reason:v.reason,command:id()});data=await api('catalog?city='+city);render();await cabinet()}
else if(f.id==='expense-form'){await api('manage/expense',{city_id:city,command:id(),amount:Math.round(Number(v.amount)*100),category:v.category,reason:v.reason});await adminContent()}
}catch(err){toast(errorText(err))}finally{if(submit)submit.disabled=false}});
async function start(){const ref=new URLSearchParams(location.search).get('ref');if(/^[A-Z0-9]{12}$/.test(ref||'')&&!read('bazar.ref',''))write('bazar.ref',ref);try{const r=await fetch('./deployment.json',{cache:'no-store'});if(r.ok){const c=await r.json();if(c.apiBase){const u=new URL(c.apiBase);if(u.protocol!=='https:'||u.pathname!=='/'||u.search||u.hash||u.username||u.password)throw Error('INVALID_API_ORIGIN');if(u.origin!==location.origin)apiBase=u.origin}}}catch{}try{boot=await api('bootstrap');user=boot.user}catch{try{const local=await fetch('./catalogue.json').then(r=>r.json());boot=local.bootstrap;data=local.catalogues[city];staticMode=true}catch{$('#app').innerHTML=`<div class="shell"><p class="loading">${esc(t('brand'))}</p><p class="hint">${esc(t('network'))}</p><button onclick="location.reload()">${esc(t('refresh'))}</button></div>`;return}}if(!boot.cities.some(c=>c.id===city)){city=boot.cities[0].id;basket=read('bazar.basket.'+city,[])}try{if(!staticMode){data=await api('catalog?city='+city);try{promotions=(await api('promotions?city='+city)).promotions}catch{promotions=[]}}render();if(location.hash==='#cabinet')await cabinet();else if(location.hash==='#orders')await myOrders();else if(new URLSearchParams(location.hash.slice(1)).has('join'))open(`<h2>${esc(t('join'))}</h2><p class="hint">${esc(t('inviteHint'))}</p><form id="join-form">${input('name','text','','required')}${input('email','email','','required')}${input('password','password','','required minlength="12" autocomplete="new-password"')}<button type="submit" class="primary">${esc(t('join'))}</button></form>`,'join')}catch(e){toast(errorText(e))}}
start();

document.addEventListener('error',e=>{if(e.target.tagName==='IMG'){e.target.hidden=true;const holder=e.target.parentElement;if(holder.classList.contains('art')){const notice=document.createElement('span');notice.className='small';notice.textContent=t('photoUnavailable');holder.append(notice)}}},true);

function promotionSections(){return ['SALE','EVENING'].map(kind=>`<section id="${kind==='SALE'?'promotions':'evening'}"><div class="section-head"><div><p class="eyebrow">${esc(t('brand'))}</p><h2>${esc(t(kind==='SALE'?'promotions':'evening'))}</h2><p>${esc(opText(lang,kind==='SALE'?33:35))}</p></div></div>${promotions.filter(p=>p.kind===kind).map(p=>`<article class="panel"><h3>${esc(name(p))}</h3><p>${esc(p.terms[lang])}</p><p>${esc(opText(lang,34))}: ${p.percent}%</p></article>`).join('')}<div class="grid">${data.products.filter(p=>p.promotion_kind===kind).map(productCard).join('')||`<p class="hint">${esc(({ru:'Сейчас действующих предложений нет. Новые появятся здесь.',hy:'Այս պահին գործող առաջարկներ չկան։ Նորերը կհայտնվեն այստեղ։',ka:'ამჟამად მოქმედი შეთავაზებები არ არის. ახალი აქ გამოჩნდება.'})[lang])}</p>`}</div></section>`).join('')}

function offerDoors(){return `<div class="market-offers">${[['promotions','tomato','saleDoor'],['evening','orange','eveningDoor']].map(([key,photo,copy])=>`<a class="offer-door ${key}" href="#${key}"><div><span class="eyebrow">${esc(t('brand'))}</span><h2>${esc(t(key))}</h2><p>${esc(t(copy))}</p><span class="offer-link">${esc(t('lookOffers'))}</span></div><img src="./media/${photo}.jpg" alt="" width="280" height="280" loading="eager"></a>`).join('')}</div>`}
function adSlot(slot){const ad=boot.advertising?.find(a=>a.slot===slot);return `<aside class="advertising-slot" data-ad-slot="${slot}" ${ad?'':'hidden'}>${ad?`<a class="project-ad" href="${esc(ad.url)}" target="_blank" rel="noopener noreferrer sponsored"><img src="${esc(ad.image)}" alt="" width="480" height="240" loading="lazy"><div><small>${esc(t('advertLabel'))}</small><h3>${esc(ad.names[lang])}</h3><p>${esc(ad.texts[lang])}</p><span>${esc(t('openProject'))}</span></div></a>`:''}</aside>`}
